    bulk: (w, b) => bulk(b, w), bulkDel: async b => { if (await sure(`تمسح ${plural(picked.size, "المنتج ده", "المنتجين دول", "منتجات", "منتج")} بصورهم؟ الأوردرات القديمة بتفضل زي ما هي.`, "امسحهم")) run(b, async () => { await post("prod-del", { ids: [...picked] }); picked.clear(); say("اتمسحوا."); await SB.reload(); await load(); }); },
    bulkCat: () => { let move = false; const p = pane({ title: "القسم", cls: "small", html: () => `<div class="sm-f"><label>ضيفهم لقسم</label>${SB.sel("cat", catOpts("اختار القسم"), 0)}</div>${SB.tog("move", false, "وشيلهم من أقسامهم القديمة")}`, foot: () => `<button type="button" class="btn" data-do="go">تمام</button>`, acts: { go: async b => { const d = SB.read(p.el); if (!+d.cat) return say("اختار القسم.", true); await bulk(b, "cat", { cat: +d.cat, move: d.move }); p.close(true); } } }); },
    bulkStock: () => { const p = pane({ title: "تعديل الكمية", cls: "small", html: () => `<p>هيتطبق على ${plural(picked.size, "منتج واحد", "منتجين", "منتجات", "منتج")} بكل مقاساتهم.</p><div class="sm-2"><div class="sm-f"><label>التعديل</label>${SB.sel("kind", [["add", "زوّد"], ["sub", "نزّل"], ["set", "خليها"]], "add")}</div>${fld("value", "كام", "", { mode: "numeric", x: "data-n autofocus" })}</div>`, foot: () => '<button type="button" class="btn" data-do="go">تمام</button>', acts: { go: async b => { const d = SB.read(p.el), v = Math.abs(+d.value || 0); await bulk(b, "stock", { kind: d.kind === "set" ? "set" : "add", value: d.kind === "sub" ? -v : v }); p.close(true); } } }); },
    tags: () => { const p = pane({ title: "تيكت السعر والباركود", cls: "small", html: () => `<p class="sub">تيكت لكل مقاس ولون، بالسعر وباركود كود المنتج.</p>${fld("n", "كام نسخة من كل تيكت", 1, { mode: "numeric", x: "data-n" })}`, foot: () => '<button type="button" class="btn" data-do="go">افتح للطباعة</button>', acts: { go: () => { window.open("api/shop.ashx?a=print&kind=tags&n=" + (SB.read(p.el).n || 1) + "&ids=" + [...picked].join(","), "_blank", "noopener"); p.close(true); } } }); },
    bulkPrice: () => { const p = pane({ title: "تعديل السعر", cls: "small", html: () => `<p>هيتطبق على ${plural(picked.size, "منتج واحد", "منتجين", "منتجات", "منتج")} بكل مقاساتهم.</p><div class="sm-2"><div class="sm-f"><label>التعديل</label>${SB.sel("dir", [["1", "زوّد"], ["-1", "نزّل"]], "1")}</div><div class="sm-f"><label>بإيه</label>${SB.sel("kind", [["pct", "نسبة %"], ["amt", "مبلغ بالجنيه"]], "pct")}</div></div>${fld("value", "قد إيه", "", { mode: "decimal", x: "data-n autofocus" })}<p class="sm-hint">مثلًا: زوّد 10% على منتج بـ 500 = 550. ده بيغيّر السعر نفسه. لو عايز خصم مؤقت، اعمل «عرض» أحسن: بيرجع لوحده.</p>`, foot: () => `<button type="button" class="btn" data-do="go">طبّق</button>`, acts: { go: async b => { const d = SB.read(p.el); if (!(d.value > 0)) return say("اكتب الرقم.", true); await bulk(b, "price", { kind: d.kind, value: d.value * +d.dir }); p.close(true); } } }); },
    xls: () => excel(), tr: () => translate()
