      oAdd: (ar, e) => { p.options.push({ n: [ar || "", e || ""], v: [] }); mark(); U("opts", optUI()); const l = o.el.querySelectorAll(".sm-opt"); const i = l[l.length - 1].querySelector(ar ? ".sm-vadd" : "input"); if (i) i.focus(); }, oDel: i => { p.options.splice(+i, 1); sync(); mark(); U("opts", optUI()); U("vars", varUI()); U("stock", stockUI()); },
