      vImg: i => { const v = p.vars[+i], ci = p.options.filter(x => x.v.length).findIndex(isColor); const q = pane({ title: "صورة " + v.o.join(" / "), cls: "small", html: () => `<div class="sm-pk">${p.images.map(x => `<button type="button" class="${v.image === x.path ? "on" : ""}" data-do="set:${encodeURIComponent(x.path)}"><img src="${esc(x.small || x.url)}" alt=""></button>`).join("")}</div>${ci >= 0 ? `<p class="sm-hint">هتتحط لكل مقاسات لون «${esc(v.o[ci])}».</p>` : ""}${v.image ? '<button type="button" class="btn ghost sm" data-do="set:">من غير صورة</button>' : ""}`, acts: { set: x => { const path = typeof x === "string" ? decodeURIComponent(x) : ""; p.vars.forEach(w => { if (ci >= 0 ? w.o[ci] === v.o[ci] : w === v) w.image = path; }); mark(); q.close(true); U("vars", varUI()); } } }); },
