      gMk: () => { p.guide = { head: ["المقاس", "الصدر", "الطول"], rows: [["S", "", ""], ["M", "", ""], ["L", "", ""]], note: "" }; mark(); U("guide", SB.guide(p.guide)); }, gRow: () => { p.guide.rows.push(p.guide.head.map(() => "")); mark(); U("guide", SB.guide(p.guide)); }, gCol: () => { p.guide.head.push(""); p.guide.rows.forEach(r => r.push("")); mark(); U("guide", SB.guide(p.guide)); }, gDel: () => { p.guide = null; mark(); U("guide", SB.guide(null)); }, gRx: i => { p.guide.rows.splice(+i, 1); mark(); U("guide", SB.guide(p.guide)); },
